(function(){
const rates=[['0.75','0,75×'],['1','1×'],['1.25','1,25×'],['1.5','1,5×'],['2','2×']];
const player=document.getElementById('quran-audio');
function applyRate(value){const rate=Number(value)||1;localStorage.setItem('quranPlaybackRate',String(rate));if(player)player.playbackRate=rate;document.querySelectorAll('.mini-speed').forEach(w=>{const b=w.querySelector('.mini-tool');if(b)b.textContent=rates.find(x=>Number(x[0])===rate)?.[1]||`${rate}×`;const s=w.querySelector('.v17-speed');if(s)s.value=String(rate)})}
function enhance(){document.querySelectorAll('.mini-speed').forEach(wrap=>{if(wrap.dataset.speedMenu==='1')return;wrap.dataset.speedMenu='1';const old=wrap.querySelector('.mini-tool'),select=wrap.querySelector('.v17-speed');if(!old||!select)return;const button=old.cloneNode(true);old.replaceWith(button);const menu=document.createElement('span');menu.className='speed-choice-menu';rates.forEach(([value,label])=>{const option=document.createElement('button');option.type='button';option.textContent=label;option.dataset.rate=value;option.addEventListener('click',event=>{event.stopPropagation();applyRate(value);wrap.classList.remove('speed-open')});menu.append(option)});wrap.append(menu);button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();document.querySelectorAll('.mini-speed.speed-open').forEach(x=>{if(x!==wrap)x.classList.remove('speed-open')});wrap.classList.toggle('speed-open')},true);select.addEventListener('change',()=>applyRate(select.value));const saved=localStorage.getItem('quranPlaybackRate')||'1';applyRate(saved)})}
document.addEventListener('click',event=>{if(!event.target.closest('.mini-speed'))document.querySelectorAll('.mini-speed.speed-open').forEach(x=>x.classList.remove('speed-open'))});
const verses=document.getElementById('verses');if(verses)new MutationObserver(enhance).observe(verses,{childList:true,subtree:true});
const style=document.createElement('style');style.textContent='.mini-speed .speed-choice-menu{display:none;position:absolute;right:0;bottom:34px;z-index:30;width:72px;padding:4px;border:1px solid var(--line);border-radius:9px;background:var(--panel);box-shadow:var(--shadow)}.mini-speed.speed-open .speed-choice-menu{display:flex;flex-direction:column;gap:2px}.speed-choice-menu button{width:100%;padding:5px 4px;border:0;border-radius:6px;background:transparent;color:var(--ink);font:inherit;font-size:11px;font-weight:700;line-height:1.2}.speed-choice-menu button:hover,.speed-choice-menu button:focus-visible{background:var(--panel2)}.speed-choice-menu button:active{background:var(--accent);color:#fff}.mini-speed .v17-speed{display:none!important}';document.head.append(style);enhance();
})();
